## Library Catalog

### Book Structure

```xiom
enum BookStatus {
  Available;
  CheckedOut;
}

type Book {
  id: Int;
  title: Str;
  author: Str;
  status: BookStatus;
  borrower: Option[Str];
}
```

### Catalog Management

```xiom
type Catalog {
  books: Vec[Book];
  next_id: Int;
}

fn add_book(catalog: &mut Catalog, title: Str, author: Str) -> Int {
  let book = Book{
    id: catalog.next_id,
    title: title,
    author: author,
    status: BookStatus.Available,
    borrower: Option.None
  };
  catalog.books.push(book);
  catalog.next_id += 1;
  catalog.next_id - 1
}
```

### Search

```xiom
fn search_by_title(catalog: &Catalog, query: Str) -> Vec<Book> {
  let mut results: Vec[Book] = Vec[Book].new();
  let mut i = 0;
  while i < catalog.books.len() {
    let book = catalog.books.get(i).unwrap();
    if book.title.contains(query) {
      results.push(book.clone());
    };
    i += 1;
  };
  results
}

fn search_by_author(catalog: &Catalog, author: Str) -> Vec<Book> {
  let mut results: Vec[Book] = Vec[Book].new();
  let mut i = 0;
  while i < catalog.books.len() {
    let book = catalog.books.get(i).unwrap();
    if book.author.contains(author) {
      results.push(book.clone());
    };
    i += 1;
  };
  results
}

fn find_by_id(catalog: &Catalog, id: Int) -> Option<Book> {
  let mut i = 0;
  while i < catalog.books.len() {
    let book = catalog.books.get(i).unwrap();
    if book.id == id { return Option.Some(book.clone()); };
    i += 1;
  };
  Option.None
}
```

### Checkout and Return

```xiom
fn checkout_book(catalog: &mut Catalog, id: Int, borrower: Str) -> Bool {
  let mut i = 0;
  while i < catalog.books.len() {
    let book = catalog.books.get(i).unwrap();
    if book.id == id && book.status == BookStatus.Available {
      catalog.books.set(i, Book{
        id: book.id, title: book.title.clone(), author: book.author.clone(),
        status: BookStatus.CheckedOut, borrower: Option.Some(borrower)
      });
      return true;
    };
    i += 1;
  };
  false
}

fn return_book(catalog: &mut Catalog, id: Int) -> Bool {
  let mut i = 0;
  while i < catalog.books.len() {
    let book = catalog.books.get(i).unwrap();
    if book.id == id && book.status == BookStatus.CheckedOut {
      catalog.books.set(i, Book{
        id: book.id, title: book.title.clone(), author: book.author.clone(),
        status: BookStatus.Available, borrower: Option.None
      });
      return true;
    };
    i += 1;
  };
  false
}
```

