type LibraryBook {
  title: Str;
  is_available: Bool;
}

type Library {
  books: Vec[LibraryBook];
}

fn add_book(lib: &mut Library, title: Str) {
  lib.books.push(LibraryBook{ title: title, is_available: true });
}

fn checkout(lib: &mut Library, index: Int) -> Bool {
  if index >= lib.books.len() { return false; };
  let book = lib.books.get(index).unwrap();
  if !book.is_available { return false; };
  lib.books.set(index, LibraryBook{ title: book.title.clone(), is_available: false });
  true
}

fn return_book(lib: &mut Library, index: Int) -> Bool {
  if index >= lib.books.len() { return false; };
  let book = lib.books.get(index).unwrap();
  if book.is_available { return false; };
  lib.books.set(index, LibraryBook{ title: book.title.clone(), is_available: true });
  true
}

fn count_available(lib: &Library) -> Int {
  let mut count = 0;
  let mut i = 0;
  while i < lib.books.len() {
    if lib.books.get(i).unwrap().is_available { count += 1; };
    i += 1;
  };
  count
}

fn main() -> Int {
  let mut lib = Library{ books: Vec[LibraryBook].new() };
  add_book(&mut lib, "Dune");
  add_book(&mut lib, "Foundation");
  add_book(&mut lib, "Neuromancer");
  checkout(&mut lib, 0);
  return_book(&mut lib, 0);
  io.println(count_available(&lib));
  return 0;
}
